// @ts-nocheck — config script read by Node (Vite plugin, lifecycle, CI).
//
// - `clients`: the business side. `distributed.clients.json` declares the
//   `$distributed` GraphQL client of `mobpit_service` (the player_stats read
//   model); `distributed build|dev ../server` generates it (lifecycle-owned,
//   never checked in).
// - `games`: the Mob Pit zone surface, generated by the Vite plugin itself
//   (dev start, Rust changes, build) and checked in CI by `npm run check:games`.
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const app = dirname(fileURLToPath(import.meta.url));
const repo = resolve(app, '../../..');
const server = resolve(app, '../server');

const inventory = JSON.parse(readFileSync(resolve(app, 'distributed.clients.json'), 'utf8'));

/** GraphQL clients from `distributed.clients.json` + how to export their surface. */
export const distributedClients = Object.freeze(
	inventory.clients.map((client) =>
		Object.freeze({
			module: client.module,
			manifest: {
				args: [
					'client-manifest',
					'--manifest-path',
					resolve(server, 'Cargo.toml'),
					'--package',
					'mobpit_service',
					'--distributed-path',
					repo
				]
			},
			surface: client.surface,
			documents: client.documents,
			out: client.output
		})
	)
);

/** @type {import('@hops-ops/distributed/sveltekit/vite').DistributedSvelteKitViteOptions} */
export const distributedViteOptions = {
	cwd: app,
	// The CLI from this checkout (an installed `distributed` works the same;
	// under `distributed build|dev` the lifecycle's own executable is used).
	command: 'cargo',
	commandArgs: ['run', '--quiet', '--manifest-path', resolve(repo, 'Cargo.toml'), '-p', 'distributed_cli', '--bin', 'distributed', '--'],
	clients: distributedClients,
	games: [
		{
			manifest: {
				args: ['game-manifest', '--manifest-path', resolve(server, 'Cargo.toml'), '--entrypoint', 'game_demos::mobpit::game_surface']
			},
			out: 'src/lib/generated/mobpit',
			// The predicted step (`pit_step`) lives in the sim crate.
			watch: [resolve(server, 'sim')]
		}
	]
};
